import sys

def main():
    data = sys.stdin.read().split()
    if len(data) < 2:
        print("-1")
        return
    s = data[0]
    t = data[1]

    if len(s) != len(t):
        print("-1")
        return

    # Check if mapping is bijective
    map_s_to_t = {}
    map_t_to_s = {}

    for a, b in zip(s, t):
        if a in map_s_to_t:
            if map_s_to_t[a] != b:
                print("-1")
                return
        else:
            map_s_to_t[a] = b

        if b in map_t_to_s:
            if map_t_to_s[b] != a:
                print("-1")
                return
        else:
            map_t_to_s[b] = a

    print("yes")

if __name__ == "__main__":
    main()
